INSERT INTO public.panda_agent_skills(id,title,enabled,active_version) VALUES ('product-evidence-qa','Product evidence Q&A',true,1);
INSERT INTO public.panda_agent_skill_versions(skill_id,version,content,content_hash,source,permissions,budget,reviewed) VALUES('product-evidence-qa',1,'# Product evidence Q&A

Use only the current approved canonical product evidence. The deterministic MCU fast path selects exact MCU fields; it does not infer wiring or board revisions. Revalidate sources, citations, ownership and the current session before protected save and public release. No model, shell, remote install or external search is permitted.
','c4ae4241b5f68357c7d05d65efc95225376dfec65c5efcf0fb23d3851828cf02','Panda-agent/skills/product-evidence-qa/v1.md','["canonical-evidence:read"]','{"modelCalls": 0, "workers": 1, "nodes": 1, "deadlineMs": 30000, "fragments": 8, "contextUnits": 20000}',true);
INSERT INTO public.panda_agent_skills(id,title,enabled,active_version) VALUES ('embedded-project-guide','Embedded project guide',false,NULL);
INSERT INTO public.panda_agent_skill_versions(skill_id,version,content,content_hash,source,permissions,budget,reviewed) VALUES('embedded-project-guide',1,'# Embedded project guide

Opt in with one board, a student goal and user-reported components. Run the bounded deterministic Python guide graph: six nodes, at most two concurrent read-only tasks, one 30-second deadline and zero model calls. Use only current approved literal MCU evidence as board facts. Render objective, BOM, architecture, interfaces, firmware outline, verification steps, open questions and citations. Label conceptual guidance and user reports. Leave TRIG/ECHO, power, revision and framework compatibility unresolved without applicable evidence. Never claim code compiled or hardware ran. Store bounded intent only; refresh facts on every run. No developer skills, shell, arbitrary tools or remote installations.
','4bb8620c3975f84b39c3d1d3b94ea45778f61f000c250983d367f924f1c35044','Panda-agent/skills/embedded-project-guide/v1.md','["canonical-evidence:read", "project-intent:read", "project-intent:write"]','{"modelCalls": 0, "workers": 2, "nodes": 6, "deadlineMs": 30000, "fragments": 8, "contextUnits": 20000}',false);
INSERT INTO public.panda_agent_skill_versions(skill_id,version,content,content_hash,source,permissions,budget,reviewed) VALUES('embedded-project-guide',2,'# Embedded project guide with observation checklist

Apply the same permissions, source policy, six-node/two-worker/30-second limits, zero model calls and eight-section format as version 1. In verification steps, additionally require a written observation checklist before applying power. A checklist is a proposed student task, never proof of a hardware test. Keep board wiring, TRIG/ECHO, power, revision and framework placeholders until applicable evidence establishes them. Memory retains bounded student intent, not source grants. No developer skills, shell, arbitrary tools or remote installations.
','485e62959ca0dbd4d7585aed319c5556965e62924db2857c5a01b12cf8bfc4bb','Panda-agent/skills/embedded-project-guide/v2.md','["canonical-evidence:read", "project-intent:read", "project-intent:write"]','{"modelCalls": 0, "workers": 2, "nodes": 6, "deadlineMs": 30000, "fragments": 8, "contextUnits": 20000}',false);
